          pm.expect(jsonData).to.have.property("member_client_id");
          pm.expect(jsonData.member_client_id).to.be.a("string");
          pm.expect(jsonData.member_client_id).to.match(
              /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
          );
      });

      pm.test("member_reference_number matches member_client_id", function () {
          pm.expect(jsonData.member_reference_number).to.eql(jsonData.member_client_id);
      });

      pm.test("internal_error_code is null", function () {
          pm.expect(jsonData).to.have.property("internal_error_code");
          pm.expect(jsonData.internal_error_code).to.be.null;
      });

      pm.test("response_message is null", function () {
          pm.expect(jsonData).to.have.property("response_message");
          pm.expect(jsonData.response_message).to.be.null;
      });

      pm.test("Response body has all required fields", function () {
          pm.expect(jsonData).to.have.all.keys(
              "response_code",
              "member_reference_number",
              "internal_error_code",
              "member_client_id",
              "response_message"
          );
      });

